@pytest.mark.parametrize('value', [1, 5.0, 'foo', [1, 2, 3, 4], (5, 6, 7, 8), {'foo', 'bar', 'baz'}, {'a': {'b': 1}}, {'a': 1, 'b': 2}, {1: 'a', 2: 'b'}, {1: [], 2: [1, 2, 3, 4]}, hl.Call([0, 1]), hl.Call([1, 0], phased=True), hl.Call([2], phased=True), hl.Call([]), hl.Call([1, 1]), hl.Call([17495, 17495])])
def test_literal_encodings(value):
    _assert_encoding_roundtrip(value)

@pytest.mark.parametrize('value', [np.array([]), np.array([1]), np.array([1, 2, 3, 4]), np.array([[1, 2], [3, 4], [5, 6]]), np.array([[[[1]], [[2]]], [[[3]], [[4]]], [[[5]], [[6]]]])])
def test_literal_ndarray_encodings(value):
    _assert_encoding_roundtrip(value)
    _assert_encoding_roundtrip(value.T)

def test_decoding_multiple_dicts():
    dict = {0: 'a', 1: 'b', 2: 'c'}
    dict2 = {0: 'x', 1: 'y', 2: 'z'}
    ht = hl.utils.range_table(1).annotate(indices=hl.array([0, 1, 2]))
    ht.select(a=ht.indices.map(lambda i: hl.struct(x=hl.dict(dict).get(i), y=hl.dict(dict2).get(i)))).collect()
